class Widget
{
    public Widget() => Render();          // a virtual call
    protected virtual void Render() { }
}

class Label : Widget
{
    string font = "Arial";                // filled before base()
    string text;
    public Label() { text = "Hello"; }    // has not run yet
    protected override void Render() =>
        Console.WriteLine($"{font}: {text.Length}");
}

